class ImageBuilder {
public:
    ImageBuilder(const std::vector<IPPrefix>& prefixes) : prefixes_(prefixes) {}

    ImageData run() {
        ImageData out;
        std::vector<IPPrefix> root0;
        std::map<uint64_t, std::vector<IPPrefix> > groups16, groups64;
        for (const IPPrefix& p : prefixes_) {
            IPPrefix n = make_prefix(p.address, p.length, p.hop);
            if (n.length <= 16) root0.push_back(n);
            else if (n.length <= 64)
                groups16[n.address.hi >> 48].push_back(n);
            else
                groups64[n.address.hi].push_back(n);
        }
        std::sort(root0.begin(), root0.end(), prefix_entry_less);
        BuildNode* root0_node = nullptr;
        if (!root0.empty())
            root0_node = build_subtree(root0, 0, 0, 16);
        std::vector<std::pair<uint64_t, BuildNode*> > roots16, roots64;
        for (auto& item : groups16) {
            std::sort(item.second.begin(), item.second.end(), prefix_entry_less);
            roots16.push_back(std::make_pair(
                item.first, build_subtree(item.second, 16, 16, 64)));
        }
        for (auto& item : groups64) {
            std::sort(item.second.begin(), item.second.end(), prefix_entry_less);
            roots64.push_back(std::make_pair(
                item.first, build_subtree(item.second, 64, 64, 128)));
        }
        assign_heights_and_stages();
        assign_cells();
        assign_bitmap_ids_and_ni();
        fill_nexthops();
        fill_banks(out);
        if (root0_node) {
            out.root.stage = root0_node->stage;
            out.root.cell = root0_node->cell;
        }
        for (const auto& item : roots16) {
            ImageFront front;
            front.key = item.first;
            front.loc.stage = item.second->stage;
            front.loc.cell = item.second->cell;
            out.front16.push_back(front);
        }
        for (const auto& item : roots64) {
            ImageFront front;
            front.key = item.first;
            front.loc.stage = item.second->stage;
            front.loc.cell = item.second->cell;
            out.front64.push_back(front);
        }
        return out;
    }

    ~ImageBuilder() {
        for (BuildNode* n : nodes_) delete n;
    }

private:
    const std::vector<IPPrefix>& prefixes_;
    std::vector<BuildNode*> nodes_;

    BuildNode* new_node(int depth, int origin, unsigned max_length,
                        const ip6_t& region) {
        BuildNode* n = new BuildNode();
        n->depth = depth;
        n->owner_origin = origin;
        n->owner_max = max_length;
        n->region = mask_ip6(region, depth);
        nodes_.push_back(n);
        return n;
    }

    BuildNode* build_subtree(const std::vector<IPPrefix>& items, int depth,
                             int origin, unsigned max_length) {
        ip6_t region = mask_ip6(items[0].address, depth);
        BuildNode* node = new_node(depth, origin, max_length, region);
        if (items.size() == 1) {
            node->type = 4;
            node->inlines.push_back(items[0]);
            return node;
        }
        if (items.size() == 2) {
            node->type = 5;
            node->inlines.push_back(items[0]);
            node->inlines.push_back(items[1]);
            return node;
        }

        std::vector<IPPrefix> local;
        std::map<uint8_t, std::vector<IPPrefix> > outer;
        bool can_have_children =
            depth + 6 <= static_cast<int>(max_length);
        for (const IPPrefix& p : items) {
            if (!can_have_children ||
                p.length < static_cast<unsigned>(depth + 6)) {
                local.push_back(p);
            } else {
                uint8_t key = static_cast<uint8_t>(
                    extract_prefix_bits(p.address, depth, 6));
                outer[key].push_back(p);
            }
        }
        uint64_t bitmap = 0;
