        out |= static_cast<uint32_t>(child->cell & 0x3fffffu) << 10;
        return out;
    }

    static const uint32_t ABSENT_CHILD = 15u << 6;

    static void pack_inline(std::bitset<256>& word, int base, int offset,
                            const IPPrefix& p, int origin) {
        uint64_t fragment = 0;
        unsigned relative = 0;
        if (origin == 0) {
            fragment = p.address.hi;
            relative = p.length;
        } else if (origin == 16) {
            fragment = (p.address.hi & 0x0000ffffffffffffULL) << 16;
            relative = static_cast<unsigned>(p.length) - 16u;
        } else {
            fragment = p.address.lo;
            relative = static_cast<unsigned>(p.length) - 64u;
        }
        set_bits(word, base, offset, 64, fragment);
        set_bits(word, base, offset + 64, 8, relative);
        set_bits(word, base, offset + 72, 22, p.hop);
    }

    void pack_node(ImageData& out, std::bitset<256>& word,
                   const BuildNode* n) const {
        int base = (n->cell & 1u) ? 128 : 0;
        set_bits(word, base, 0, 3, n->type);
        set_bits(word, base, 3, 22, n->bmp);
        if (n->type == 4 || n->type == 5) {
            pack_inline(word, base, 25, n->inlines[0], n->owner_origin);
            if (n->type == 5)
                pack_inline(word, base, 119, n->inlines[1],
                            n->owner_origin);
            return;
        }
        set_bits(word, base, 25, 16, n->bitmap_id);
        set_bits(word, base, 41, 22, n->ni_base);
        if (n->type == 1) {
            for (int i = 0; i < 2; ++i) {
                uint32_t raw = ABSENT_CHILD;
                if (i < static_cast<int>(n->children.size()))
                    raw = pack_child(n->child_keys[i], n->children[i]);
                set_bits(word, base, 63 + i * 32, 32, raw);
            }
        } else if (n->type == 2) {
            for (int i = 0; i < 6; ++i) {
                uint32_t raw = ABSENT_CHILD;
                if (i < static_cast<int>(n->children.size()))
                    raw = pack_child(n->child_keys[i], n->children[i]);
                set_bits(word, base, 63 + i * 32, 32, raw);
            }
        } else {
            set_bits(word, base, 63, 64, n->bulk_bitmap);
            set_bits(word, base, 127, 22, n->bulk_base);
            set_bits(word, base, 149, 4, n->bulk_stage);
            for (int i = 0; i < 3; ++i) {
                uint32_t raw = ABSENT_CHILD;
                if (i < n->direct_count)
                    raw = pack_child(n->child_keys[i], n->children[i]);
                set_bits(word, base, 153 + i * 32, 32, raw);
            }
        }
    }

    void fill_banks(ImageData& out) {
        std::vector<IPPrefix> sorted = prefixes_;
        std::sort(sorted.begin(), sorted.end(), prefix_entry_less);
        for (BuildNode* n : nodes_) n->bmp = bmp_for(n, sorted);

        std::vector<uint32_t> cell_count(RAM_NUM, 0);
        for (BuildNode* n : nodes_) {
            uint32_t extent = 2;
            if (!n->bulk_parent && (n->type == 1 || n->type == 4))
                extent = 1;
            uint32_t end = n->cell + extent;
            if (end > cell_count[n->stage]) cell_count[n->stage] = end;
        }
        for (int s = 0; s < RAM_NUM; ++s) {
            out.cells[s] = cell_count[s];
            out.banks[s].assign((cell_count[s] + 1) / 2,
                                std::bitset<256>());
        }
        for (BuildNode* n : nodes_) {
            std::bitset<256>& word = out.banks[n->stage][n->cell >> 1];
            pack_node(out, word, n);
        }
        out.bitmaps = bitmaps_;
        out.nexthops = nexthops_;
    }

    std::vector<uint64_t> bitmaps_;
    std::vector<uint32_t> nexthops_;
};

} // namespace

ImageData build_image(const std::vector<IPPrefix>& prefixes) {
    ImageBuilder builder(prefixes);
    return builder.run();
}

bool MemoryImage::load(const ImageData& proposed) {
    std::vector<IPPrefix> decoded;
    if (!validate_image_data(proposed, decoded)) return false;
    FibTable next;
    for (const IPPrefix& p : decoded)
        next.put(p.address, p.length, p.hop);
    data_ = proposed;
    table_ = std::move(next);
    return true;
}

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    return table_.lookup(ip);
}
